input.content:
workspace "Sistema de Agendamento" "Agendamentos com lembretes por SMS." {

    !identifiers hierarchical

    model {
        usuario = person "Usuário" "Pessoa que usa o sistema de agendamento."

        agendamento = softwareSystem "Sistema de Agendamento" "Gerencia agendamentos e envia lembretes por SMS." {
            mobile = container "App Mobile" "Permite ao usuário gerenciar agendamentos pelo celular." "Flutter" "Mobile App"
            painel = container "Painel Web" "Permite ao usuário gerenciar agendamentos pelo navegador." "Vue" "Web Browser"
            api = container "API" "Expõe as operações de agendamento e dispara os lembretes por SMS." "Python, FastAPI"
            db = container "Banco de Dados" "Guarda os agendamentos." "PostgreSQL 15" "Database"
        }

        twilio = softwareSystem "Twilio" "Serviço externo de envio de SMS." "External"

        usuario -> agendamento.mobile "Usa"
        usuario -> agendamento.painel "Usa"
        agendamento.mobile -> agendamento.api "Consome a API de agendamentos de"
        agendamento.painel -> agendamento.api "Consome a API de agendamentos de"
        agendamento.api -> agendamento.db "Lê e grava agendamentos em" "SQL"
        agendamento.api -> twilio "Envia lembretes por SMS através de"
        twilio -> usuario "Entrega lembretes por SMS a" "SMS"
    }

    views {
        systemContext agendamento "SystemContext" {
            include *
            autoLayout lr
        }

        container agendamento "Containers" {
            include *
            autoLayout lr
        }

        styles {
            element "Person" {
                shape person
                background #08427b
                color #ffffff
            }
            element "Software System" {
                background #1168bd
                color #ffffff
            }
            element "Container" {
                background #438dd5
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Mobile App" {
                shape mobileDeviceLandscape
            }
            element "Web Browser" {
                shape webBrowser
            }
            element "Database" {
                shape cylinder
            }
        }

        theme default
    }

    configuration {
        scope softwaresystem
    }

}

